package net.sourceforge.plantuml.teavm;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;

import org.junit.jupiter.api.Test;

/**
 * The skins embedded in {@link EmbeddedResources} are generated by
 * {@link EmbeddedResourcesGenerator} from the files of src/main/resources/skin.
 * Nothing regenerates them when those files change, and a stale copy only shows
 * in the TeaVM builds (wrong font sizes, missing styles), so this test compares
 * them with the cleaned skin files.
 */
class EmbeddedResourcesTest {

	private static final String HOW_TO_FIX = "EmbeddedResources.java is out of date: run "
			+ "net.sourceforge.plantuml.teavm.EmbeddedResourcesGenerator from the root of the repository "
			+ "to regenerate it.";

	private static String read(InputStream is) throws IOException {
		final ByteArrayOutputStream out = new ByteArrayOutputStream();
		final byte[] buffer = new byte[4096];
		int len;
		while ((len = is.read(buffer)) != -1)
			out.write(buffer, 0, len);
		return new String(out.toByteArray(), StandardCharsets.UTF_8);
	}

	@Test
	void embeddedPlantumlSkinIsUpToDate() throws IOException {
		final String expected = EmbeddedResourcesGenerator.readCleanedSkin("src/main/resources/skin/plantuml.skin");
		assertEquals(expected, read(EmbeddedResources.openPlantumlSkin()), HOW_TO_FIX);
	}

	@Test
	void embeddedStrictSkinIsUpToDate() throws IOException {
		final String expected = EmbeddedResourcesGenerator.readCleanedSkin("src/main/resources/skin/strictuml.skin");
		assertEquals(expected, read(EmbeddedResources.openStrictSkin()), HOW_TO_FIX);
	}

}
